import functools
import hashlib
import json

import redis

_client = None


def get_redis_client(url="redis://localhost:6379/0"):
    global _client
    if _client is None:
        _client = redis.Redis.from_url(url, decode_responses=True)
    return _client


def _make_key(prefix, args, kwargs):
    raw = json.dumps([args, kwargs], sort_keys=True, default=repr)
    digest = hashlib.sha256(raw.encode()).hexdigest()
    return f"cache:{prefix}:{digest}"


def redis_cache(ttl=300, prefix=None):
    def decorator(func):
        key_prefix = prefix or f"{func.__module__}.{func.__qualname__}"

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = _make_key(key_prefix, args, kwargs)
            client = get_redis_client()
            try:
                cached = client.get(key)
                if cached is not None:
                    return json.loads(cached)
            except redis.RedisError:
                return func(*args, **kwargs)
            result = func(*args, **kwargs)
            try:
                client.setex(key, ttl, json.dumps(result, default=str))
            except (redis.RedisError, TypeError):
                pass
            return result

        wrapper.invalidate = lambda *a, **k: get_redis_client().delete(
            _make_key(key_prefix, a, k)
        )
        return wrapper

    return decorator


